import { computed, defineComponent, h, inject, provide, ref, useId, type ComputedRef, type InjectionKey, type PropType } from 'vue';
import { getTabsListVariantKey, getTabsState, tabsStyleKeys } from '../lib/core';
import type { TabsListVariant, TabsOrientation } from '../lib/core';
import styles from './tabs.module.scss';

interface TabsContextValue {
	value: string;
	orientation: TabsOrientation;
	baseId: string;
	select: (value: string) => void;
}

type TabsContext = ComputedRef<TabsContextValue>;

const TabsContextKey: InjectionKey<TabsContext> = Symbol('tile-tabs');

export const TTabs = defineComponent({
	name: 'TTabs',
	props: {
		modelValue: { type: String, default: undefined },
		defaultValue: { type: String, default: '' },
		orientation: {
			type: String as PropType<TabsOrientation>,
			default: 'horizontal',
		},
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, slots }) {
		const internalValue = ref(props.defaultValue);
		const currentValue = computed(() => (props.modelValue !== undefined ? props.modelValue : internalValue.value));
		const baseId = useId();

		const context = computed<TabsContextValue>(() => ({
			value: currentValue.value,
			orientation: props.orientation,
			baseId,
			select: (next: string) => {
				if (props.modelValue === undefined) {
					internalValue.value = next;
				}
				emit('update:modelValue', next);
				emit('change', next);
			},
		}));

		provide(TabsContextKey, context);

		return () => h('div', { class: styles[tabsStyleKeys.root], 'data-orientation': props.orientation }, slots.default?.());
	},
});

export const TTabsList = defineComponent({
	name: 'TTabsList',
	props: {
		variant: {
			type: String as PropType<TabsListVariant>,
			default: 'default',
		},
	},
	setup(props, { slots }) {
		const context = inject(TabsContextKey);
		if (!context) {
			throw new Error('TTabsList must be used within <TTabs>.');
		}

		const variantKey = computed(() => getTabsListVariantKey(props.variant));
		const isVertical = computed(() => context!.value.orientation === 'vertical');

		function handleKeydown(event: KeyboardEvent) {
			const nextKey = isVertical.value ? 'ArrowDown' : 'ArrowRight';
			const prevKey = isVertical.value ? 'ArrowUp' : 'ArrowLeft';
			const isNext = event.key === nextKey;
			const isPrev = event.key === prevKey;
			const isHome = event.key === 'Home';
			const isEnd = event.key === 'End';

			if (!isNext && !isPrev && !isHome && !isEnd) {
				return;
			}

			const triggers = Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('button[role="tab"]')).filter((trigger) => !trigger.disabled);

			if (triggers.length === 0) {
				return;
			}

			const currentIndex = triggers.indexOf(document.activeElement as HTMLButtonElement);
			let nextIndex: number;
			if (isHome) {
				nextIndex = 0;
			} else if (isEnd) {
				nextIndex = triggers.length - 1;
			} else {
				const direction = isNext ? 1 : -1;
				nextIndex = (currentIndex + direction + triggers.length) % triggers.length;
			}

			const nextTrigger = triggers[nextIndex];
			nextTrigger?.focus();

			const nextValue = nextTrigger?.getAttribute('data-value');
			if (nextValue !== null && nextValue !== undefined) {
				context!.value.select(nextValue);
			}

			event.preventDefault();
		}

		return () =>
			h(
				'div',
				{
					class: [styles[tabsStyleKeys.list], styles[variantKey.value]],
					role: 'tablist',
					'data-orientation': context.value.orientation,
					'data-variant': props.variant,
					onKeydown: handleKeydown,
				},
				slots.default?.(),
			);
	},
});

export const TTabsTrigger = defineComponent({
	name: 'TTabsTrigger',
	props: {
		value: { type: String, required: true },
		disabled: { type: Boolean, default: false },
	},
	setup(props, { slots }) {
		const context = inject(TabsContextKey);
		if (!context) {
			throw new Error('TTabsTrigger must be used within <TTabs>.');
		}

		const active = computed(() => context.value.value === props.value);
		const state = computed(() => getTabsState(active.value));
		const triggerId = computed(() => `${context.value.baseId}-trigger-${props.value}`);
		const contentId = computed(() => `${context.value.baseId}-content-${props.value}`);

		return () =>
			h(
				'button',
				{
					type: 'button',
					id: triggerId.value,
					role: 'tab',
					'aria-selected': active.value,
					'aria-controls': contentId.value,
					'data-value': props.value,
					tabindex: active.value ? 0 : -1,
					disabled: props.disabled,
					'data-state': state.value,
					'data-orientation': context.value.orientation,
					class: styles[tabsStyleKeys.trigger],
					onClick: () => context.value.select(props.value),
				},
				slots.default?.(),
			);
	},
});

export const TTabsContent = defineComponent({
	name: 'TTabsContent',
	props: {
		value: { type: String, required: true },
	},
	setup(props, { slots }) {
		const context = inject(TabsContextKey);
		if (!context) {
			throw new Error('TTabsContent must be used within <TTabs>.');
		}

		const active = computed(() => context.value.value === props.value);
		const state = computed(() => getTabsState(active.value));
		const contentId = computed(() => `${context.value.baseId}-content-${props.value}`);
		const triggerId = computed(() => `${context.value.baseId}-trigger-${props.value}`);

		return () =>
			h(
				'div',
				{
					id: contentId.value,
					role: 'tabpanel',
					'aria-labelledby': triggerId.value,
					'data-state': state.value,
					'data-orientation': context.value.orientation,
					hidden: !active.value,
					class: styles[tabsStyleKeys.content],
				},
				slots.default?.(),
			);
	},
});

export default TTabs;

@use '../../../styles/variables/colors' as *;

.root {
	display: flex;
	gap: $spacing-2;

	&[data-orientation='horizontal'] {
		flex-direction: column;
	}

	&[data-orientation='vertical'] {
		flex-direction: row;
	}
}

.list {
	display: inline-flex;
	width: fit-content;
	align-items: center;
	justify-content: center;
	border-radius: $radius-lg;
	padding: 3px;
	background-color: $muted;
	color: $muted-foreground;
	transition: background-color $transition-fast;
	outline: none;

	&:focus-visible {
		box-shadow:
			0 0 0 2px $background,
			0 0 0 4px $ring;
	}

	[data-orientation='horizontal'] & {
		height: 2.25rem;
	}

	[data-orientation='vertical'] & {
		height: fit-content;
		flex-direction: column;
	}

	// 变体
	&.variantLine {
		gap: $spacing-1;
		background-color: transparent;
		border-radius: 0;

		.trigger[data-state='active'] {
			background-color: transparent;
			box-shadow: none;

			&::after {
				content: '';
				position: absolute;
				background-color: $foreground;
			}
		}

		&[data-orientation='horizontal'] .trigger[data-state='active']::after {
			left: 0;
			right: 0;
			bottom: -5px;
			height: 2px;
		}

		&[data-orientation='vertical'] .trigger[data-state='active']::after {
			top: 0;
			bottom: 0;
			right: -4px;
			width: 2px;
		}
	}
}

.trigger {
	position: relative;
	display: inline-flex;
	flex: 1;
	align-items: center;
	justify-content: center;
	gap: $spacing-1_5;
	border: 1px solid transparent;
	border-radius: $radius-md;
	padding: $spacing-1 $spacing-2;
	font-size: $text-sm;
	font-weight: $font-medium;
	white-space: nowrap;
	color: $muted-foreground;
	transition:
		color $transition-fast,
		box-shadow $transition-fast;
	outline: none;
	user-select: none;

	&:hover {
		color: $foreground;
	}

	&:focus-visible {
		border-color: $ring;
		box-shadow: 0 0 0 3px rgba($ring, 0.5);
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
	}

	&[data-state='active'] {
		background-color: $background;
		color: $foreground;
		box-shadow: $shadow-sm;
	}

	[data-orientation='vertical'] & {
		width: 100%;
		justify-content: flex-start;
	}

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
		flex-shrink: 0;
	}
}

.content {
	flex: 1;
	border-radius: $radius;
	outline: none;

	&:focus-visible {
		box-shadow: 0 0 0 3px rgba($ring, 0.5);
	}
}
